# Short proton-proton distances (< 5 A, the NOE range) in ideal secondary structures, computed from backbone
# coordinates built with standard bond lengths and angles (NeRF construction; HN, HA and one HB per residue).
# A: an alpha helix of 14 residues (phi = -57, psi = -47 deg); B: a two-stranded antiparallel beta sheet
#    (strands of 7 residues, phi = -139, psi = 135 deg; the second strand is generated by a twofold rotation
#    about an axis normal to the sheet, its offset chosen to optimize the N-H...O=C hydrogen bonds).
# Each matrix element (i, j) shows the shortest distance of a classified proton pair between residues i and j:
# dNN (HN-HN), dalphaN (HA(i)-HN(j)) and dalphaalpha (HA-HA), colored by distance; residues of the second strand
# are numbered 9-15 after a two-residue turn that is not modeled. The pattern identifies the secondary
# structure: helices give dNN(i, i+1) and dalphaN(i, i+3); antiparallel strands give strong dalphaN(i, i+1),
# cross-strand dalphaalpha at non-hydrogen-bonded pairs and cross-strand dNN at hydrogen-bonded pairs.
import matplotlib.pyplot as plt
import numpy as np
from scipy.optimize import minimize

import wikibio as bio
from wikibio import charts

P = bio.P


def place(a, b, c, bond, angle, torsion):
    """Position of atom d from a, b, c with |cd| = bond, angle bcd and torsion abcd (degrees)."""
    angle, torsion = np.radians(angle), np.radians(torsion)
    bc = c - b
    bc /= np.linalg.norm(bc)
    n = np.cross(b - a, bc)
    n /= np.linalg.norm(n)
    m = np.cross(n, bc)
    d2 = np.array([-bond * np.cos(angle), bond * np.sin(angle) * np.cos(torsion), bond * np.sin(angle) * np.sin(torsion)])
    return c + d2[0] * bc + d2[1] * m + d2[2] * n


def backbone(n, phi, psi, omega=180.0):
    N = [np.array([0.0, 1.458, 0.0])]
    CA = [np.array([0.0, 0.0, 0.0])]
    C = [np.array([1.525, 0.0, 0.0])]
    C[0] = place(N[0] + np.array([1.0, 1.0, 0.0]), N[0], CA[0], 1.525, 111.2, -60.0)
    O = []
    for i in range(n):
        if i > 0:
            N.append(place(N[i - 1], CA[i - 1], C[i - 1], 1.329, 116.2, psi))
            CA.append(place(CA[i - 1], C[i - 1], N[i], 1.458, 121.7, omega))
            C.append(place(C[i - 1], N[i], CA[i], 1.525, 111.2, phi))
    for i in range(n):
        nxt = place(N[i], CA[i], C[i], 1.329, 116.2, psi)
        O.append(place(nxt, CA[i], C[i], 1.231, 120.5, 180.0) if False else place(N[i], CA[i], C[i], 1.231, 120.5,
                                                                                    psi + 180.0))
    N, CA, C, O = map(np.array, (N, CA, C, O))
    H, HA, HB = [], [], []
    for i in range(n):
        if i > 0:
            u1 = (C[i - 1] - N[i]) / np.linalg.norm(C[i - 1] - N[i])
            u2 = (CA[i] - N[i]) / np.linalg.norm(CA[i] - N[i])
            h = -(u1 + u2)
            H.append(N[i] + 1.01 * h / np.linalg.norm(h))
        else:
            H.append(np.full(3, np.nan))
        b = CA[i] - N[i]
        c = C[i] - CA[i]
        a = np.cross(b, c)
        cb = -0.58273431 * a + 0.56802827 * b - 0.54067466 * c + CA[i]
        us = [(x - CA[i]) / np.linalg.norm(x - CA[i]) for x in (N[i], C[i], cb)]
        ha = -sum(us)
        HA.append(CA[i] + 1.09 * ha / np.linalg.norm(ha))
        HB.append(place(N[i], CA[i], cb, 1.09, 109.5, 180.0))
    return dict(N=N, CA=CA, C=C, O=O, H=np.array(H), HA=np.array(HA), HB=np.array(HB))


def classify(res):
    """Shortest classified H-H distance matrix and its type (0 dNN, 1 daN, 2 daa) per residue pair."""
    n = len(res["H"])
    D = np.full((n, n), np.inf)
    T = np.zeros((n, n), int)
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            cand = ((np.linalg.norm(res["H"][i] - res["H"][j]), 0),
                    (np.linalg.norm(res["HA"][i] - res["H"][j]), 1),
                    (np.linalg.norm(res["HA"][j] - res["H"][i]), 1),
                    (np.linalg.norm(res["HA"][i] - res["HA"][j]), 2))
            cand = [c for c in cand if np.isfinite(c[0])]
            d, t = min(cand)
            D[i, j], T[i, j] = d, t
    return D, T


# helix
hel = backbone(14, -57.0, -47.0)

# sheet: strand A, then strand B by a twofold rotation about an axis normal to the sheet
st = backbone(7, -139.0, 135.0)
ax_vec = st["CA"][-1] - st["CA"][0]
ax_vec /= np.linalg.norm(ax_vec)
nh = np.nanmean([st["H"][i] - st["N"][i] for i in range(1, 7, 2)], axis=0)
y = nh - nh.dot(ax_vec) * ax_vec
y /= np.linalg.norm(y)
z = np.cross(ax_vec, y)
center = st["CA"].mean(axis=0)


def rotate(res, shift, dist, tilt):
    R = -np.eye(3) + 2 * np.outer(z, z)      # 180 degree rotation about z
    p0 = center + (dist / 2) * y + shift * ax_vec
    out = {}
    for k, v in res.items():
        out[k] = (v - p0) @ R.T + p0 + tilt * 0
    return out


def hb_cost(x):
    """Hydrogen bonds from the amides pointing towards strand B: H...O = 2.0 A and N-H...O linear."""
    b = rotate(st, x[0], x[1], 0)
    cost = 0.0
    for i in (1, 3, 5):
        d = np.linalg.norm(b["O"] - st["H"][i], axis=1)
        k = np.argmin(d)
        u = (st["H"][i] - st["N"][i]) / 1.01
        v = (b["O"][k] - st["H"][i]) / d[k]
        cost += (d[k] - 2.0) ** 2 + (1 - u.dot(v))
    return cost


grid = [(hb_cost([a, b]), a, b) for a in np.linspace(-3.5, 3.5, 71) for b in np.linspace(4.0, 6.5, 26)]
_, a0, b0 = min(grid)
xopt = minimize(hb_cost, [a0, b0], method="Nelder-Mead").x
sb = rotate(st, xopt[0], xopt[1], 0)
sheet = {k: np.concatenate([st[k], sb[k]]) for k in st}   # sb[0] lies opposite st[6]: hairpin order

fig, axs = plt.subplots(1, 2, figsize=(11.0, 5.0))
cmap = plt.get_cmap("viridis_r")
marks = ("s", "o", "D")
names = ("dNN (Hᴺ–Hᴺ)", "dαN (Hᵅ–Hᴺ)", "dαα (Hᵅ–Hᵅ)")
for ax, res, title, labels in ((axs[0], hel, "A   α helix", list(range(1, 15))),
                               (axs[1], sheet, "B   Antiparallel β sheet (two strands)",
                                list(range(1, 8)) + list(range(9, 16)))):
    D, T = classify(res)
    n = len(D)
    for i in range(n):
        for j in range(i + 1, n):
            if D[i, j] < 5.0:
                ax.scatter(j, i, s=(6.0 - D[i, j]) ** 2 * 14, c=[cmap((D[i, j] - 2.0) / 3.0)], marker=marks[T[i, j]],
                           edgecolors="none")
    ax.set_xlim(-0.7, n - 0.3)
    ax.set_ylim(n - 0.3, -0.7)
    ax.set_xticks(range(n))
    ax.set_xticklabels(labels, fontsize=7)
    ax.set_yticks(range(n))
    ax.set_yticklabels(labels, fontsize=7)
    ax.set_aspect("equal")
    ax.plot([-0.7, n], [-0.7, n], color=P.muted(), lw=0.5)
    charts.style_axes(ax, "residue j", "residue i", box=True)
    charts.title(ax, title)
    if n == 14 and labels[7] == 9:
        ax.axhline(6.5, color=P.muted(), lw=0.6, ls=":")
        ax.axvline(6.5, color=P.muted(), lw=0.6, ls=":")
for m, nm in zip(marks, names):
    axs[1].scatter([], [], marker=m, c=[cmap(0.3)], s=40, label=nm)
axs[1].legend(fontsize=7.5, frameon=False, loc="lower left")
sm = plt.cm.ScalarMappable(cmap=cmap, norm=plt.Normalize(2.0, 5.0))
cb = fig.colorbar(sm, ax=axs, shrink=0.7, pad=0.02)
cb.set_label("H–H distance / Å", fontsize=8, color=P.ink())
cb.ax.tick_params(labelsize=7, colors=P.muted())
